UPDATE WORKSPACES
   SET WS_NAME = #{wsName, jdbcType=VARCHAR},
       WS_DESCRIPTION = #{wsDescription, jdbcType=VARCHAR},
       WS_TYPE = #{wsType, jdbcType=VARCHAR},
       JOIN_TYPE = #{joinType, jdbcType=VARCHAR}
    
        
           , WS_IMAGE_PATH = NULL
           , WS_IMAGE_ORIGINAL_PATH = NULL
           , WS_IMAGE_CROP_SCALE = NULL
           , WS_IMAGE_CROP_X = NULL
           , WS_IMAGE_CROP_Y = NULL
        
        
           , WS_IMAGE_PATH = #{wsImagePath, jdbcType=VARCHAR}
           , WS_IMAGE_ORIGINAL_PATH = #{wsImageOriginalPath, jdbcType=VARCHAR}
           , WS_IMAGE_CROP_SCALE = #{wsImageCropScale, jdbcType=NUMERIC}
           , WS_IMAGE_CROP_X = #{wsImageCropX, jdbcType=NUMERIC}
           , WS_IMAGE_CROP_Y = #{wsImageCropY, jdbcType=NUMERIC}
        
    
 WHERE WS_ID = #{wsId}

UPDATE WS_MEMBERS 
SET WS_ROLE = #{role}
WHERE WS_ID = #{wsId} AND USER_ID = #{userId}

UPDATE WORKSPACES 
SET OWNER_ID = #{ownerId} 
WHERE WS_ID = #{wsId}

mapper.select:
SELECT COUNT(*)
FROM WS_MEMBERS
WHERE WS_ID = #{wsId}
  AND USER_ID = #{userId}

SELECT COUNT(*)
FROM WS_MEMBERS
WHERE WS_ID = #{wsId}
  AND USER_ID = #{userId}
  AND WS_ROLE = 'ADMIN'

SELECT COUNT(*)
  FROM WS_JOIN_REQUESTS
 WHERE WS_ID = #{wsId}
   AND REQUESTER_ID = #{userId}
   AND STATUS = 'PENDING'

mapper.insert:
INSERT INTO WS_JOIN_REQUESTS (
    REQUEST_ID, WS_ID, REQUESTER_ID, STATUS, REQUESTED_AT, UPDATED_AT
) VALUES (
    SEQ_WS_JOIN_REQUEST_ID.NEXTVAL, #{wsId}, #{userId}, 'PENDING', SYSDATE, SYSDATE
)

mapper.update:
UPDATE WS_JOIN_REQUESTS
   SET STATUS = 'CANCELLED',
       UPDATED_AT = SYSDATE
 WHERE WS_ID = #{wsId}
   AND REQUESTER_ID = #{userId}
   AND STATUS = 'PENDING'

mapper.select:
SELECT STATUS
  FROM (
        SELECT STATUS
          FROM WS_JOIN_REQUESTS
         WHERE WS_ID = #{wsId}
           AND REQUESTER_ID = #{userId}
         ORDER BY REQUESTED_AT DESC, REQUEST_ID DESC
  )
 WHERE ROWNUM = 1

