UPDATE WS_JOIN_REQUESTS
   SET STATUS = 'CANCELLED',
       UPDATED_AT = SYSDATE
 WHERE REQUEST_ID = #{requestId}
   AND REQUESTER_ID = #{userId}
   AND STATUS = 'APPROVED'

UPDATE WS_JOIN_REQUESTS
   SET STATUS = 'COMPLETED',
       UPDATED_AT = SYSDATE
 WHERE REQUEST_ID = #{requestId}
   AND REQUESTER_ID = #{userId}
   AND STATUS = 'APPROVED'
